<?php
require_once __DIR__.'/auth.php';require_once __DIR__.'/../workflow_support.php';require_once __DIR__.'/../conversation_support.php';
if($_SESSION['role']==='admin'){header('Location: dashboard.php');exit;}
$q=$pdo->prepare('SELECT * FROM complaints WHERE assigned_staff_id=? ORDER BY CASE WHEN status<>\'resolved\' AND due_date<CURDATE() THEN 0 ELSE 1 END,COALESCE(due_date,\'9999-12-31\'),id DESC');$q->execute([$_SESSION['user_id']]);$reports=$q->fetchAll(PDO::FETCH_ASSOC);
$open=count(array_filter($reports,fn($c)=>$c['status']!=='resolved'));$overdue=count(array_filter($reports,fn($c)=>$c['status']!=='resolved'&&$c['due_date']&&$c['due_date']<date('Y-m-d')));$unread=unreadConversationCounts($pdo,(int)$_SESSION['user_id'],true);
?>
<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Staff workspace — Barangay Mudiang</title><link rel="stylesheet" href="../assets/vendor/bootstrap.min.css"><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css"><?php include __DIR__.'/../ui_theme.php'; ?></head><body class="portal-page resident-directory"><?php include __DIR__.'/operations_nav.php'; ?><main class="main"><header class="topbar"><div class="topbar-left"><h1>Staff workspace</h1><p>Your assigned cases and resident conversations</p></div><a class="btn btn-outline" href="messages.php">Open messages</a></header><div class="content"><section class="dashboard-intro"><div><span class="portal-kicker">Service team / My responsibility</span><h2>Move your assigned reports forward.</h2><p>Acknowledge concerns, record action taken, and keep residents informed.</p></div><span class="intro-tag"><?= $open ?> open · <?= $overdue ?> overdue</span></section><section class="card mb-4"><div class="card-header"><h2>My assigned complaints</h2></div><div class="table-wrap"><table><thead><tr><th>Report</th><th>Resident</th><th>Status</th><th>Importance</th><th>Target completion</th><th>Next action</th></tr></thead><tbody><?php foreach($reports as $c): ?><tr><td>#<?= (int)$c['id'] ?> · <?= reportActivityEscape($c['complaint_type']) ?></td><td><?= reportActivityEscape($c['complainant_name']) ?></td><td><?= ucfirst($c['status']) ?></td><td><?= ucfirst($c['priority']) ?></td><td><?= reportActivityEscape($c['due_date']?:'Not scheduled') ?><?php if($c['due_date']&&$c['due_date']<date('Y-m-d')&&$c['status']!=='resolved'): ?> <strong class="text-danger">Overdue</strong><?php endif; ?></td><td><a class="btn btn-primary" href="edit_complaint.php?id=<?= (int)$c['id'] ?>">Review<?php if(!empty($unread[$c['id']])): ?> · <?= (int)$unread[$c['id']] ?> new messages<?php endif; ?></a></td></tr><?php endforeach;if(!$reports): ?><tr><td colspan="6"><div class="empty-state"><strong>No complaints assigned yet</strong><p>Your administrator will assign reports to your account. You will receive an assignment notification.</p></div></td></tr><?php endif; ?></tbody></table></div></section><section class="card"><div class="card-header"><h2>Your responsibilities and limits</h2></div><div class="card-body"><p>You can view assigned reports and evidence, acknowledge and process cases, add remarks and completion evidence, resolve cases with closing notes, and message the resident.</p><p>Assignment, importance, deadlines, account management, the resident directory, annual reports and system-wide analytics are controlled by administrators. Your Activity Logs show your own recorded actions; a report's history remains visible while it is assigned to you.</p><p>Follow Filed → Acknowledged → Processing → Resolved. Residents can request reopening if the concern remains unresolved. Report corrections or scheduling changes to your administrator.</p></div></section></div></main><?php include __DIR__.'/notification_widget.php'; ?></body></html>
